import sys
import xml.etree.ElementTree as ET
from xml.sax.saxutils import unescape

def main():
    try:
        xml_path = sys.stdin.readline().strip()
        item_name = sys.stdin.readline().strip()

        tree = ET.parse(xml_path)
        root = tree.getroot()

        for item in root.findall('item'):
            if item.get('name') == item_name:
                value = item.get('value')
                if value is not None:
                    # Handle entity resolution by parsing the DOCTYPE
                    doc = ET.parse(xml_path)
                    root = doc.getroot()
                    if root.find('{http://www.w3.org/XML/1998/namespace}doctype') is not None:
                        doctype = root.find('{http://www.w3.org/XML/1998/namespace}doctype')
                        if doctype is not None:
                            entities = {}
                            for entity in doctype.findall('{http://www.w3.org/XML/1998/namespace}entity'):
                                name = entity.get('{http://www.w3.org/XML/1998/namespace}name')
                                value = entity.get('{http://www.w3.org/XML/1998/namespace}value')
                                if name and value:
                                    entities[name] = value
                            # Replace entities in the value
                            for name, replacement in entities.items():
                                value = value.replace('&' + name + ';', replacement)
                            value = unescape(value)
                    print(value)
                    sys.exit(0)
        print('NOT_FOUND')
        sys.exit(0)
    except (IOError, ET.ParseError):
        print('ERROR')
        sys.exit(1)

if __name__ == '__main__':
    main()
